      const a = rec("ABL"), b = rec("BCL"), R = H.rivals[next.opp], stars = [0, 1, 3, 8].map(i => H.roster[i]), last = H.practiceTrend[H.practiceTrend.length - 1], mixp = H.seasonPlay.map((p, i) => ({ k: p.k, v: Math.round(p.freq), c: PC[i % 6] }));
